from textual.app import ComposeResult, App
from textual.widgets import Header, Footer, Tree, Static
from textual.containers import Horizontal
from textual.binding import Binding
import os
from pathlib import Path

class TextViewer(Static):
    """Simple text viewer panel."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._content = "Select a file to view"

    def render(self):
        return self._content

    def update_content(self, text):
        self._content = text
        self.refresh()

class DirectoryBrowser(App):
    """File browser with directory tree and text viewer."""

    CSS = """
    Screen {
        layout: vertical;
    }

    Horizontal {
        width: 1fr;
        height: 1fr;
    }

    #tree {
        width: 30;
        border: solid green;
    }

    #viewer {
        width: 1fr;
        border: solid blue;
        overflow: auto;
    }
    """

    BINDINGS = [
        Binding("q", "quit", "Quit"),
    ]

    def compose(self) -> ComposeResult:
        yield Header()
        with Horizontal():
            yield Tree("📁 Home", id="tree")
            yield TextViewer(id="viewer")
        yield Footer()

    def on_mount(self) -> None:
        tree = self.query_one(Tree)
        home = Path.home()
        tree.root.data = home
        self._load_tree(tree.root, home)

    def _load_tree(self, node, path: Path) -> None:
        """Load directory tree recursively."""
        try:
            items = sorted(path.iterdir(), key=lambda p: (not p.is_dir(), p.name))
            for item in items[:25]:
                if item.name.startswith('.'):
                    continue
                label = ("📁 " if item.is_dir() else "📄 ") + item.name
                child = node.add(label)
                child.data = item

                if item.is_dir() and item.name not in ['.git', '__pycache__', 'node_modules', '.venv', 'venv']:
                    self._load_tree(child, item)
        except (PermissionError, OSError):
            pass

    def on_tree_select(self, message: Tree.Selected) -> None:
        """Handle file selection."""
        path = message.node.data
        viewer = self.query_one(TextViewer)

        if not isinstance(path, Path):
            return

        if path.is_dir():
            viewer.update_content(f"📁 Directory: {path.name}\n\nContents:\n" + 
                                "\n".join(f"  {p.name}" for p in list(path.iterdir())[:20]))
        else:
            try:
                with open(path, 'r', encoding='utf-8', errors='replace') as f:
                    content = f.read()
                viewer.update_content(content[:10000])
            except Exception as e:
                viewer.update_content(f"Error: {e}")

if __name__ == "__main__":
    DirectoryBrowser().run()

